"""Chat-tuning conversations generated by rules from Planalto law pages (docs/llm-lab.md §9.5).

Each law gives a card (its name and summary, the ementa) read from the captured page. Fixed
Portuguese templates then ask for an article, for what a law covers, and which law covers a
summary; every answer is the law's own text with its citation. Whole laws are held out.
"""

import json
import random
import re
from collections.abc import Sequence
from dataclasses import dataclass
from pathlib import Path

from agavus.corpus.statutes import decode_html, html_to_text
from agavus.model.federal import PUBLIC_DOMAIN
from agavus.model.planalto import PLANALTO_DIR, SITE
from agavus.model.sft import Conversation

# Headings like "LEI Nº 11.340, DE 7 DE AGOSTO DE 2006", whose words may wrap across lines.
HEADING = re.compile(
  r"(?im)^\s*(LEI\s+COMPLEMENTAR|LEI\s+DELEGADA|DECRETO-LEI|LEI)\s+N\s*[.º°o]*\s*"
  r"(\d[\d.]*)\s*,?\s*DE\s+(\d{1,2})\s*[º°o]?\s+(?:DE\s+)?([A-ZÀ-Ü]+)\s+DE\s+(\d{4})"
)
# What follows the ementa: the enacting clause or the first article (case kept for "Art.").
ENACTING = re.compile(
  r"(?m)^\s*(?:(?i:(?:O|A)\s+(?:PRESIDENT[EA]|VICE[-\u2013\s]PRESIDENTE)|Faço\s+saber"
  r"|O\s+Congresso\s+Nacional)|Art\.?\s*1(?!\d))"
)
NOTE = re.compile(
  r"\((?:Vide|Redação|Incluíd|Revogad|Regulament|Vigência|Produção|Convers|Promulga)[^)]*\)",
  re.IGNORECASE,
)
# Page labels around the ementa: "Vigência", "Mensagem de veto", conversion notes, links.
LABELS = re.compile(
  r"(?i)^(?:(?:Vigência|Mensagem\s+de\s+veto|Regulamento|Texto\s+compilado"
  r"|Produção\s+de\s+efeitos?|Conversão\s+d[ae]\s+(?:Medida\s+Provisória|MPv)\s+n[º°o.]*\s*"
  r"[\d.\-]+(?:,\s*de\s+\d{4})?\)?|Vide\s.*?,\s*de\s+(?:\d{1,2}\.\d{1,2}\.)?\d{4}\)?)[\s.]*)+"
)
TRAILERS = re.compile(
  r"(?i)(?:\s*(?:Texto\s+(?:compilado|atualizado|para\s+impressão)|Up|Down|Vigência"
  r"|Mensagem\s+de\s+veto))+$"
)
ARTICLE = re.compile(r"^Art\.?\s*(\d+(?:\.\d{3})*)\s*([ºo°])?(-[A-Za-z]+)?")
KINDS = {"LEI": "Lei", "LEI COMPLEMENTAR": "Lei Complementar", "LEI DELEGADA": "Lei Delegada"}
REVERSE_CHARS = 300

ARTICLE_QUESTIONS = (
  "O que diz o art. {n} {da} {name}?",
  "Qual é o texto do art. {n} {da} {name}?",
  "Me mostre o art. {n} {da} {name}.",
  "Transcreva o artigo {n} {da} {name}.",
)
EMENTA_QUESTIONS = (
  "Do que trata {a} {name}?",
  "Qual é a ementa {da} {name}?",
  "Sobre o que dispõe {a} {name}?",
  "Resuma o objeto {da} {name}.",
)
REVERSE_QUESTIONS = (
  "Qual lei {summary}?",
  "Que norma {summary}?",
  "Qual é a lei que {summary}?",
  "Você sabe qual lei {summary}?",
)


@dataclass(frozen=True)
class LawCard:
  """A law page's citable name and its summary (ementa)."""

  url: str
  name: str
  ementa: str


def _name(found: re.Match[str]) -> str:
  """'Lei nº 11.340, de 7 de agosto de 2006' from a heading in any case."""
  kind, number, day, month, year = found.groups()
  kind = " ".join(kind.upper().split())
  title = KINDS.get(kind, "Decreto-Lei")
  shown = "1º" if int(day) == 1 else str(int(day))
  return f"{title} nº {number.rstrip('.')}, de {shown} de {month.lower()} de {year}"


def law_card(url: str, payload: bytes) -> LawCard | None:
  """The card for a captured law page, or None when it has no recognizable heading."""
  text = html_to_text(decode_html(payload))
  # The heading precedes the enacting clause; later matches are laws the text cites.
  enacting = ENACTING.search(text)
  heading = HEADING.search(text, 0, enacting.start() if enacting else len(text))
  if heading is None:
    return None
  block = text[heading.end() : enacting.start()] if enacting else ""
  block = " ".join(NOTE.sub(" ", block).split()).lstrip(" .")
  block = TRAILERS.sub("", LABELS.sub("", block))
  ementa = re.sub(r"\s+([.,;])", r"\1", block).strip()
  return LawCard(url, _name(heading), ementa)


def article_number(origin_ref: str, text: str) -> str:
  """The number as the article writes it ('1º', '12-C'), else the one in its citation."""
  found = ARTICLE.match(text)
  if found is None:
    return origin_ref.rpartition("art. ")[2]
  number, ordinal, suffix = found.groups()
  return number + ("º" if ordinal else "") + (suffix or "")


def _conversation(source: str, question: str, answer: str, origin_ref: str) -> Conversation:
  turns = (("user", question), ("assistant", answer))
  return Conversation(turns, source, origin_ref, PUBLIC_DOMAIN)


def _card_conversations(
  card: LawCard, articles: Sequence[tuple[str, str]], chooser: random.Random
) -> list[Conversation]:
  """Every template that applies to one law."""
  masculine = card.name.startswith("Decreto")
  words = {"name": card.name, "da": "do" if masculine else "da", "a": "o" if masculine else "a"}
  found = []
  for origin_ref, text in articles:
    n = article_number(origin_ref, text)
    question = chooser.choice(ARTICLE_QUESTIONS).format(n=n, **words)
    answer = f"{text}\n\nFonte: {card.name}, art. {n}."
    found.append(_conversation("rules:article", question, answer, origin_ref))
  if not card.ementa:
    return found
  question = chooser.choice(EMENTA_QUESTIONS).format(**words)
  answer = f"{card.ementa}\n\nFonte: {card.name}."
  found.append(_conversation("rules:ementa", question, answer, card.url))
  if len(card.ementa) < REVERSE_CHARS:
    summary = (card.ementa[:1].lower() + card.ementa[1:]).rstrip(" .")
    question = chooser.choice(REVERSE_QUESTIONS).format(summary=summary)
    found.append(_conversation("rules:reverse", question, f"{card.name}.", card.url))
  return found


def rule_conversations(
  cards: Sequence[LawCard], articles_by_url: dict[str, list[tuple[str, str]]], *, seed: int
) -> list[Conversation]:
  """Conversations for every card, in url order; the seed picks each paraphrase."""
  chooser = random.Random(seed)
  return [
    conversation
    for card in sorted(cards, key=lambda card: card.url)
    for conversation in _card_conversations(card, articles_by_url.get(card.url, []), chooser)
  ]


def law_of(conversation: Conversation) -> str:
  """The law url a conversation cites: its origin_ref before any ', art. N'."""
  return conversation.origin_ref.partition(", ")[0]


def split_by_law(
  conversations: Sequence[Conversation], every: int = 10
) -> tuple[list[Conversation], list[Conversation]]:
  """(train, held-out): every `every`-th law by sorted url is held out whole."""
  laws = sorted({law_of(conversation) for conversation in conversations})
  held = {law for index, law in enumerate(laws) if index % every == every - 1}
  train = [conversation for conversation in conversations if law_of(conversation) not in held]
  return train, [conversation for conversation in conversations if law_of(conversation) in held]


def load_rule_sources(
  data_dir: Path,
) -> tuple[list[LawCard], dict[str, list[tuple[str, str]]]]:
  """Cards and (origin_ref, text) articles per law url from the Planalto crawl.

  Article rows name the consolidated page they came from; the card is read from that
  page's capture, so both sides cite the same url.
  """
  folder = data_dir / PLANALTO_DIR
  articles: dict[str, list[tuple[str, str]]] = {}
  for path in sorted((folder / "articles").rglob("*.jsonl")):
    for line in path.read_text(encoding="utf-8").splitlines():
      if line:
        row = json.loads(line)
        articles.setdefault(str(row["url"]), []).append((str(row["origin_ref"]), str(row["text"])))
  cards = []
  for url in sorted(articles):
    capture = folder / "sources" / f"{url.removeprefix(SITE)}.html"
    if capture.is_file():
      card = law_card(url, capture.read_bytes())
      if card is not None:
        cards.append(card)
  return cards, articles
